var temperature = 31.5;

// Interpolation with a format specifier
var summary = $"{city}: {temperature:F1} C";

// Raw string literal: quotes need no escaping, common indentation is stripped
var payload = """
    { "city": "Recife", "temperature": 31.5 }
    """;

// Switch expression with relational patterns
var band = temperature switch
{
    < 15 => "cold",
    < 25 => "mild",
    _ => "hot",
};

Console.WriteLine(summary);   // Recife: 31.5 C
Console.WriteLine(band);      // hot
