public static class Guards
{
    // class constraint: reference types only, and null is rejected
    public static T Require<T>(T? value, string name) where T : class =>
        value ?? throw new ArgumentNullException(name);

    // new() constraint: the type needs a public parameterless constructor
    public static T Create<T>() where T : new() => new();
}

public static class GuardDemo
{
    public static void Main()
    {
