static async IAsyncEnumerable<int> CountdownAsync(int start)
{
    for (var value = start; value > 0; value--)
    {
        await Task.Delay(50);
        yield return value;
    }
}

await foreach (var value in CountdownAsync(3))
{
    Console.WriteLine(value);   // 3, 2, 1
}

static int ParsePort(string raw)
{
    try
    {
        var port = int.Parse(raw);
        return port is >= 1 and <= 65535
            ? port
            : throw new ArgumentOutOfRangeException(nameof(raw), "port must be 1-65535");
    }
    catch (FormatException error)
    {
        // Wrap the failure and keep the original exception as the cause
        throw new ArgumentException($"not a number: {raw}", nameof(raw), error);
    }
}

try
{
    Console.WriteLine(ParsePort("8080"));
    Console.WriteLine(ParsePort("eighty"));
}
catch (Exception error) when (error is ArgumentException or FormatException)
